@page "/chat"
@rendermode InteractiveServer
@using sv_503de2392e814ff9b75cab68d5a8e66b.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    @* ── Left Sidebar: Channel List ── *@
    <aside class="chat-sidebar" role="navigation" aria-label="Channels">
        <div class="sidebar-header">
            <h2>Channels</h2>
        </div>
        <ul class="channel-list">
            @foreach (var channel in _channels)
            {
                <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                    @onclick="() => SelectChannelAsync(channel)" role="button">
                    <div class="channel-name"># @channel.Name</div>
                    <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="unread-badge">@channel.UnreadCount</span>
                    }
                </li>
            }
        </ul>
    </aside>

    @* ── Main Message Area ── *@
    <main class="chat-main @(_threadOpen ? "" : "chat-main-full")">
        @if (_activeChannel is not null)
        {
            <div class="main-header">
                <h3># @_activeChannel.Name</h3>
                <span class="main-header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScrollAsync">
                @if (_loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var msg in _messages)
                {
                    <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                         @onmouseleave="() => _hoveredMessageId = null">
                        <div class="message-header">
                            <span class="msg-author">@msg.Author</span>
                            <span class="msg-time">@FormatRelativeTime(msg.SentAt)</span>
                        </div>
                        <div class="msg-content">@msg.Content</div>

                        @if (msg.Reactions.Count > 0)
                        {
                            <div class="msg-reactions">
                                @foreach (var reaction in msg.Reactions)
                                {
                                    <button class="reaction-badge"
                                            @onclick="() => ToggleReactionAsync(msg.Id, reaction.Emoji)"
                                            title="@string.Join(", ", reaction.Users)">
                                        @reaction.Emoji @reaction.Users.Count
                                    </button>
                                }
                            </div>
                        }

                        @if (_hoveredMessageId == msg.Id)
                        {
                            <div class="msg-actions">
                                <button class="action-btn" @onclick="() => OpenThread(msg)" title="Reply in thread">💬 Reply</button>
                                <div class="emoji-picker-wrapper">
                                    <button class="action-btn" @onclick="() => ToggleEmojiPicker(msg.Id)" title="Add reaction">😀+</button>
                                    @if (_emojiPickerMessageId == msg.Id)
                                    {
                                        <div class="emoji-picker">
                                            @foreach (var emoji in _commonEmojis)
                                            {
                                                <button class="emoji-option" @onclick="() => AddReactionFromPickerAsync(msg.Id, emoji)">@emoji</button>
                                            }
                                        </div>
                                    }
                                </div>
                            </div>
                        }

                        @{ var thread = _threadSummaries.GetValueOrDefault(msg.Id); }
                        @if (thread is not null)
                        {
                            <button class="thread-link" @onclick="() => OpenThread(msg)">
                                @thread.ReplyCount @(thread.ReplyCount == 1 ? "reply" : "replies") ·
                                last @FormatRelativeTime(thread.LastReplyAt)
                            </button>
                        }
                    </div>
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="_newMessage" @bind:event="oninput"
                          @onkeydown="OnMainKeyDownAsync"
                          placeholder="Message #@_activeChannel.Name" rows="2"></textarea>
                <button class="send-btn" @onclick="SendMainMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessage)">Send</button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    @* ── Right Panel: Thread View ── *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="chat-thread-panel" role="complementary" aria-label="Thread">
            <div class="thread-header">
                <h4>Thread</h4>
                <button class="thread-close-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>
            <div class="thread-root-quote">
                <span class="msg-author">@_threadRootMessage.Author</span>
                <span class="msg-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                <p>@_threadRootMessage.Content</p>
            </div>
            <div class="thread-replies" @ref="_threadListRef">
                @foreach (var reply in _threadReplies)
                {
                    <div class="message-row">
                        <div class="message-header">
                            <span class="msg-author">@reply.Author</span>
                            <span class="msg-time">@FormatRelativeTime(reply.SentAt)</span>
                        </div>
                        <div class="msg-content">@reply.Content</div>
                        @if (reply.Reactions.Count > 0)
                        {
                            <div class="msg-reactions">
                                @foreach (var reaction in reply.Reactions)
                                {
                                    <button class="reaction-badge"
                                            @onclick="() => ToggleReactionAsync(reply.Id, reaction.Emoji)"
                                            title="@string.Join(", ", reaction.Users)">
                                        @reaction.Emoji @reaction.Users.Count
                                    </button>
                                }
                            </div>
                        }
                    </div>
                }
            </div>
            <div class="message-input-area">
                <textarea @bind="_threadReplyText" @bind:event="oninput"
                          @onkeydown="OnThreadKeyDownAsync"
                          placeholder="Reply…" rows="2"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">Reply</button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    // ── State ──
    private List<Channel> _channels = [];
    private int? _activeChannelId;
    private Channel? _activeChannel;

    private List<Message> _messages = [];
    private int _skip;
    private bool _hasMoreMessages = true;
    private bool _loadingOlder;
    private string _newMessage = "";

    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];
    private string _threadReplyText = "";

    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    private ElementReference _messageListRef;
    private ElementReference _threadListRef;
    private IJSObjectReference? _jsModule;

    // ── Lifecycle ──

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-503de2392e814ff9b75cab68d5a8e66b/Components/Pages/Chat.razor.js");
        }
    }

    // ── Channel Selection ──

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == _activeChannelId)
            return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _messages.Clear();
        _skip = 0;
        _hasMoreMessages = true;
        _threadSummaries.Clear();

        await LoadMessagesAsync();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();

        await ScrollToBottomAsync();
    }

    // ── Message Loading ──

    private async Task LoadMessagesAsync()
    {
        var batch = await ChatService.GetMessagesAsync(_activeChannelId!.Value, _skip, PageSize);
        if (batch.Count < PageSize)
            _hasMoreMessages = false;

        _messages.InsertRange(0, batch);
        _skip += batch.Count;

        await BuildThreadSummariesAsync(batch);
    }

    private async Task BuildThreadSummariesAsync(List<Message> newMessages)
    {
        // For each message that has replies (check via the service), build a summary.
        foreach (var msg in newMessages.Where(m => m.ReplyToId is null))
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                _threadSummaries[msg.Id] = new ThreadSummary(
                    msg.Id,
                    thread.Count,
                    thread.Max(t => t.SentAt));
            }
        }
    }

    private async Task OnMessageListScrollAsync()
    {
        if (!_hasMoreMessages || _loadingOlder || _jsModule is null)
            return;

        var scrollTop = await _jsModule.InvokeAsync<double>("getScrollTop", _messageListRef);
        if (scrollTop < 50)
        {
            _loadingOlder = true;
            StateHasChanged();

            var prevHeight = await _jsModule.InvokeAsync<double>("getScrollHeight", _messageListRef);
            await LoadMessagesAsync();
            StateHasChanged();

            // Preserve scroll position after prepending older messages
            await Task.Yield();
            await _jsModule.InvokeVoidAsync("preserveScroll", _messageListRef, prevHeight);

            _loadingOlder = false;
        }
    }

    // ── Sending Messages ──

    private async Task SendMainMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessage) || _activeChannelId is null)
            return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessage.Trim(), null);
        _messages.Add(sent);
        _newMessage = "";

        await ScrollToBottomAsync();
    }

    private async Task OnMainKeyDownAsync(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMainMessageAsync();
        }
    }

    // ── Reactions ──

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionFromPickerAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ToggleReactionAsync(messageId, emoji);
    }

    private async Task ToggleReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh the message in the active list
        if (_activeChannelId is not null)
        {
            var updated = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _skip);
            _messages = updated;
        }

        // Refresh thread replies if the thread is open
        if (_threadOpen && _threadRootMessage is not null)
        {
            _threadReplies = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        }
    }

    // ── Thread Panel ──

    private async void OpenThread(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadReplyText = "";
        _threadOpen = true;
        _emojiPickerMessageId = null;

        StateHasChanged();
        await ScrollThreadToBottomAsync();
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies.Clear();
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null || _activeChannelId is null)
            return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootMessage.Id);
        _threadReplies.Add(reply);
        _threadReplyText = "";

        // Update thread summary in main view
        _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(
            _threadRootMessage.Id,
            _threadReplies.Count,
            reply.SentAt);

        await ScrollThreadToBottomAsync();
    }

    private async Task OnThreadKeyDownAsync(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Scroll Helpers ──

    private async Task ScrollToBottomAsync()
    {
        await Task.Yield();
        if (_jsModule is not null)
            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListRef);
    }

    private async Task ScrollThreadToBottomAsync()
    {
        await Task.Yield();
        if (_jsModule is not null)
            await _jsModule.InvokeVoidAsync("scrollToBottom", _threadListRef);
    }

    // ── Formatting ──

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length > 40 ? string.Concat(desc.AsSpan(0, 37), "...") : desc;
    }

    // ── Cleanup ──

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            await _jsModule.DisposeAsync();
        }
    }
}

